const helpers = this.helpers;
const input = $input.first().json;
const produto = input.produto || '';
const data_de = input.data_de || '';
const data_ate = input.data_ate || '';
const filial = input.filial || '';
const armazem = input.armazem || '';

const BASE_URL = 'http://69.64.55.114:8093/scriptcase/app/GRUPOPQ/blank_analista_estoque/';
const LIMITE_AGREGACAO = 200; // acima disso, agrega em vez de devolver linha a linha
const MAX_PAGINAS = 50; // trava de seguranca: 50 x 8.000 = ate 400.000 linhas

function montarUrl(offset) {
  const qs = [];
  if (produto) qs.push('produto=' + encodeURIComponent(produto));
  qs.push('data_de=' + encodeURIComponent(data_de));
  qs.push('data_ate=' + encodeURIComponent(data_ate));
  if (filial) qs.push('filial=' + encodeURIComponent(filial));
  if (armazem) qs.push('armazem=' + encodeURIComponent(armazem));
  qs.push('offset=' + offset);
  return BASE_URL + '?' + qs.join('&');
}

async function buscarPagina(offset) {
  return await helpers.httpRequest({ method: 'GET', url: montarUrl(offset), json: true });
}

function numero(v) {
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
}

// -- Pagina 1 -----------------------------------------------------------
const pagina1 = await buscarPagina(0);
if (!pagina1 || pagina1.ok !== true) {
  throw new Error('Kardex API retornou erro: ' + JSON.stringify(pagina1 && pagina1.erro));
}

// total_periodo e o campo novo (paginacao); total sozinho e fallback pra API antiga
const totalPeriodo = (pagina1.total_periodo != null) ? pagina1.total_periodo : pagina1.total;

// Caso pequeno: tudo ja veio na pagina 1, devolve cru (mesmo comportamento de sempre)
if (totalPeriodo <= LIMITE_AGREGACAO) {
  return [{ json: pagina1 }];
}

// Caso grande: agrega, buscando TODAS as paginas antes de responder
const amostra = (pagina1.movimentos || []).slice(0, 20);
const porCfop = {};
const porProduto = {};
let totalEntradasQtd = 0, totalSaidasQtd = 0, totalEntradasValor = 0, totalSaidasValor = 0;
let processadas = 0;

function acumula(movimentos) {
  for (const m of (movimentos || [])) {
    const cfopRaw = m.CFOP;
    const cfop = (typeof cfopRaw === 'string' ? cfopRaw.trim() : cfopRaw) || 'SEM_CFOP';
    const prod = m.CODPROD || 'SEM_PRODUTO';
    porCfop[cfop] = (porCfop[cfop] || 0) + 1;
    porProduto[prod] = (porProduto[prod] || 0) + 1;
    const kardex = (m.KARDEX || '').toUpperCase();
    const qtd = numero(m.QTD);
    const custo = numero(m.CUSTO);
    if (kardex === 'ENTRADAS') {
      totalEntradasQtd += qtd;
      totalEntradasValor += qtd * custo; // CUSTO em ENTRADAS e unitario -> valor = QTD*CUSTO
    }
    if (kardex === 'SAIDAS') {
      totalSaidasQtd += qtd;
      totalSaidasValor += custo; // CUSTO em SAIDAS ja e o valor total baixado (CMV)
    }
  }
  processadas += (movimentos || []).length;
}

acumula(pagina1.movimentos);

let paginaAtual = pagina1;
let paginasLidas = 1;
while (paginaAtual.tem_mais && paginasLidas < MAX_PAGINAS) {
  paginaAtual = await buscarPagina(paginaAtual.proximo_offset);
  if (!paginaAtual || paginaAtual.ok !== true) break; // fica com o que ja acumulou em vez de falhar tudo
  acumula(paginaAtual.movimentos);
  paginasLidas += 1;
}

const topProdutos = Object.entries(porProduto).sort((a, b) => b[1] - a[1]).slice(0, 15).map(([codprod, count]) => ({ codprod, ocorrencias: count }));
const topCfops = Object.entries(porCfop).sort((a, b) => b[1] - a[1]).slice(0, 15).map(([cfop, count]) => ({ cfop, ocorrencias: count }));

// tem_mais e o sinal correto (API paginada). Se a API ainda nao tem paginacao
// (tem_mais ausente/undefined), cai pro campo legado 'truncado' -- sem isso,
// !undefined vira true e a resposta MENTE dizendo cobertura completa mesmo
// quando a pagina unica veio cortada pela API antiga.
const cobriuTudo = (paginaAtual.tem_mais !== undefined) ? !paginaAtual.tem_mais : !paginaAtual.truncado;

let aviso = `Consulta ampla demais para retornar linha a linha (${totalPeriodo} movimentos no total). Resposta agregada automaticamente para nao estourar o contexto da conversa. Peca um produto especifico ou um periodo mais curto se precisar dos dados linha a linha.`;
if (!cobriuTudo) {
  aviso += ` ATENCAO: os totais abaixo sao PARCIAIS, nao cobrem o periodo inteiro (parou em ${paginasLidas} pagina(s), ~${processadas} movimentos processados). Peca um periodo mais curto ou um produto especifico pra numeros completos.`;
}

return [{
  json: {
    aviso,
    total_movimentos: totalPeriodo,
    movimentos_processados: processadas,
    cobertura_completa: cobriuTudo,
    paginas_lidas: paginasLidas,
    total_entradas_qtd: totalEntradasQtd,
    total_saidas_qtd: totalSaidasQtd,
    total_entradas_valor: totalEntradasValor,
    total_saidas_valor: totalSaidasValor,
    top_produtos_por_num_movimentos: topProdutos,
    top_cfops_por_num_movimentos: topCfops,
    amostra_primeiras_20_linhas: amostra
  }
}];
